//! 🧪️ Actual original disposer body and final Box release share the neutral close corpus.
use super::*;
use semio_framework_value::{retirement::controlled::ControlledRetirement};

struct OriginalDisposer { body:Option<ControlledRetirement<String>>, started:bool }
impl ArtifactOwnedDisposer<String> for OriginalDisposer {
 fn retirement_demands(&self,_:&String,copy:usize)->Result<RetirementDemand,ValueError>{
  if let Some(body)=self.body.as_ref(){return Ok(RetirementDemand{copy_bytes:body.next_copy_byte_demand()?,capacity_bytes:body.next_capacity_byte_demand(copy)?,release_bytes:body.next_release_byte_demand()?,depth:body.next_depth_demand()?});}
  Ok(RetirementDemand{copy_bytes:if self.started{0}else{std::mem::size_of::<String>()},depth:1,..Default::default()})
 }
 fn close_step(&mut self,source:&mut String,grant:RetainedCloneGrant)->Result<PluginLifecycleStep,Fault>{
  if let Some(body)=self.body.as_mut(){let step=body.step(grant).map_err(|error|Fault::from(error.into_message()))?;if body.terminal_is_empty(){self.body=None;}return Ok(PluginLifecycleStep::retained(step,self.terminal_is_empty(source)));}
  let original=std::mem::take(source);self.body=Some(ControlledRetirement::new(original).unwrap_or_else(|_|panic!("String owns its physical field cursor")));self.started=true;Ok(PluginLifecycleStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<String>(),..Default::default()}))
 }
 fn terminal_is_empty(&self,source:&String)->bool{self.started&&self.body.is_none()&&source.capacity()==0}
 fn terminal_frame_release_bytes(&self)->Option<usize>{(self.started&&self.body.is_none()).then_some(std::mem::size_of::<Self>())}
}

#[test]
fn original_disposer_frame_has_its_own_physical_release(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();assert_eq!(corpus["stages"].as_array().unwrap().len(),ORIGINAL_STORE_LANES.len());
 for denied in corpus["cases"].as_array().unwrap().iter().filter(|row|!row["advanced"].as_bool().unwrap()){let axis=denied["name"].as_str().unwrap();assert!(axis.starts_with("deny-"));}
 let mut source=String::with_capacity(257);source.push_str("Original German ä and English Draw presence");let original_pointer=source.as_ptr();let body_capacity=source.capacity();
 let mut disposer:ArtifactDisposal<String>=Some(Box::new(OriginalDisposer{body:None,started:false}));let bytes=std::mem::size_of::<OriginalDisposer>();let demand=original_disposal_demands(&disposer,&source,7).unwrap();
 for denial in [RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes-1,maximum_depth:demand.depth,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:0,..Default::default()}]{let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut source,denial));let (step,ready)=result.unwrap();assert!(!ready);assert_eq!(step.progress(),Some(Default::default()));assert_eq!(source.as_ptr(),original_pointer);assert_eq!(source.capacity(),body_capacity);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let mut released=0;let mut saw_frame=false;
 for _ in 0..4096{let demand=original_disposal_demands(&disposer,&source,7).unwrap();let terminal=disposer.as_ref().unwrap().terminal_is_empty(&source);if terminal{assert_eq!(demand.release_bytes,bytes);let denied=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:bytes-1,maximum_depth:demand.depth};let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut source,denied));assert!(!result.unwrap().1);assert!(disposer.is_some());assert_eq!(heap.released_bytes,0);saw_frame=true;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut source,grant));let (step,ready)=result.unwrap();let receipt=step.progress().expect("actual original physical receipt");assert!(receipt.fits(grant));assert_eq!(receipt.retained_capacity_bytes,heap.requested_bytes);assert_eq!(receipt.released_bytes,heap.released_bytes);released+=heap.released_bytes;if ready{assert!(terminal);assert!(disposer.is_none());break;}}
 assert!(saw_frame&&disposer.is_none());assert_eq!(released,body_capacity+bytes+semio_framework_value::retirement::owned_retirement_birth_bytes::<String>());assert_eq!(source.capacity(),0);
}

#[test]
fn original_transient_detach_allocates_no_replacement_and_retires_exact_frames(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();assert_eq!(corpus["detach"]["allocated"],0);assert_eq!(corpus["detach"]["released"],0);
 let ((mut store,mut disposer),birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let store=store::TransientStore::<crate::NoTransient,crate::NoTransientMutation>::default();let disposer:ArtifactDisposal<_>=Some(crate::no_transient_store_disposer());(store,disposer)});
 let original=store.current_root();let pointer=std::sync::Arc::as_ptr(&original);drop(original);let demand=original_disposal_demands(&disposer,&store,7).unwrap();assert_eq!(demand.capacity_bytes,0);assert_eq!(demand.release_bytes,0);
 for denied in [RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes-1,maximum_depth:demand.depth,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:0,..Default::default()}]{let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut store,denied));assert!(!result.unwrap().1);assert!(!store.detached_terminal_is_empty());let alias=store.current_root();assert_eq!(std::sync::Arc::as_ptr(&alias),pointer);drop(alias);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_depth:demand.depth,..Default::default()};let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut store,grant));let (step,ready)=result.unwrap();assert!(!ready);assert_eq!(step.progress().unwrap().copied_bytes,demand.copy_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(store.detached_terminal_is_empty());
 let mut allocated=birth.requested_bytes;let mut released=0;let mut denied_capacity=false;let mut denied_release=false;
 for _ in 0..4096{let demand=original_disposal_demands(&disposer,&store,7).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};if demand.capacity_bytes>0&&!denied_capacity{let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut store,RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant}));assert!(!result.unwrap().1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));denied_capacity=true;}if demand.release_bytes>0&&!denied_release{let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut store,RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}));assert!(!result.unwrap().1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));denied_release=true;}let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||original_disposal_step(&mut disposer,&mut store,grant));let (step,ready)=result.unwrap();let receipt=step.progress().unwrap();assert!(receipt.fits(grant));assert_eq!(receipt.retained_capacity_bytes,heap.requested_bytes);assert_eq!(receipt.released_bytes,heap.released_bytes);allocated+=heap.requested_bytes;released+=heap.released_bytes;if ready{break;}}
 assert!(denied_capacity&&denied_release&&disposer.is_none());assert_eq!(allocated,released);let (_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(store));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
}
